# Which tests a card runs for the files it changed (tests/run.sh card; read by tests/card-pick.js).
#
# One line per rule:   <path pattern>  <what>  [names…]
# Every line whose pattern matches a changed file counts (they add up). A changed file no line matches makes
# the card wide for its side, so nothing goes untested: found a gap? Add a line here.
#
# Patterns: * is anything but "/", ** is anything. A pattern with no "/" is matched against the file's name alone.
#
# What:
#   skip          nothing to run for it (documents)
#   rust  names…  files of src-tauri/src/testing/tests by name (no .rs; * allowed), or a raw cargo filter (has "::").
#                 The unit tests inside the changed file itself always run too, so "rust" alone means only those.
#   window names… specs of tests/ui/specs by name (.spec.mjs optional; * allowed). fits.spec.mjs, the node tests and
#                 scripts/check-window.mjs always run with them.
#   node          the node tests only (tests/*.test.js, tests/ui/*.test.js)
#   self          the changed file is itself a test: run it
#   run command…  a command, from the repository's top folder
#   wide-rust / wide-window / wide   shared ground: the full suite for that side (both, for wide)
#
# A set is named once and used as @name:   set <name> = names…

# ---- nothing to run
docs/**        skip
work/**        skip
site/**        skip
*.md           skip
LICENSE        skip
.gitignore     skip

# ---- shared ground: no safe narrow set
tests/run.sh                         wide
package.json                         wide-window
package-lock.json                    wide-window
src-tauri/Cargo.toml                 wide-rust
src-tauri/Cargo.lock                 wide-rust
src-tauri/xtask/Cargo.toml           wide-rust
src-tauri/.cargo/**                  wide-rust
.cargo/**                            wide-rust
scripts/test-runner.sh               wide-rust
src-tauri/build.rs                   wide-rust
src-tauri/src/lib.rs                 wide-rust
src-tauri/src/main.rs                wide-rust
src-tauri/src/model.rs               wide-rust
src-tauri/src/safe_git.rs            wide-rust
src-tauri/src/hub/**                 wide-rust
src-tauri/src/db/**                  wide-rust
src-tauri/src/locking/**             wide-rust
src-tauri/src/testing/*.rs           wide-rust
src-tauri/src/testing/tests/mod.rs   wide-rust
src-tauri/src/desk/mod.rs            wide-rust
src-tauri/src/desk/model.rs          wide-rust
src-tauri/src/desk/state.rs          wide-rust
src-tauri/src/desk/parse.rs          wide-rust
src-tauri/src/desk/hub/mod.rs        wide-rust
src-tauri/src/desk/hub/core/**       wide-rust
tests/ui/bridge.js                   wide-window
tests/ui/load.js                     wide-window
tests/ui/app.html                    wide-window
tests/ui/mini.html                   wide-window
tests/ui/serve.mjs                   wide-window
tests/ui/playwright.config.mjs       wide-window
tests/ui/fakes/**                    wide-window
tests/ui/scenarios/**                wide-window
tests/ui/specs/cue.mjs               wide-window
tests/ui/specs/clock.mjs             wide-window
tests/ui/specs/layout.mjs            wide-window
tests/ui/specs/pills.mjs             wide-window
scripts/check-window.mjs             wide-window
ui/index.html                        wide-window
ui/app.js                            wide-window
ui/window.js                         wide-window
ui/app/**                            wide-window
ui/core/**                           wide-window
ui/chat/**                           wide-window
ui/box/**                            wide-window
ui/styles/base.css                   wide-window
ui/styles/box.css                    wide-window
ui/styles/chat.css                   wide-window
ui/styles/messages.css               wide-window

# ---- tests that changed run themselves
src-tauri/src/testing/tests/*.rs     self
tests/ui/specs/*.spec.mjs            self
tests/*.test.js                      node
tests/ui/*.test.js                   node
tests/card-tests.map                 node
tests/card-pick.js                   node
src-tauri/src/testing/tests/typing_support.rs   rust typing typing_edges typing_failures
src-tauri/src/hosted/**             rust hosted::
src-tauri/tests/hook_asks.rs         run cd src-tauri && cargo test -q --test hook_asks
src-tauri/tests/hook_events.rs       run cd src-tauri && cargo test -q --test hook_events
src-tauri/xtask/src/**               run cd src-tauri && cargo test -q -p xtask
src-tauri/xtask/tests/**             run cd src-tauri && cargo test -q -p xtask
tests/release/**                     run tests/release/gates.test.sh
tests/release/**                     run tests/release/debug_only.test.sh
scripts/release.sh                   run tests/release/gates.test.sh
scripts/full-run.sh                  run tests/release/full_run.test.sh
tests/release/full_run.test.sh       run tests/release/full_run.test.sh

# ---- the window, by area
set desk-window = desk-* inbox-desk screens
ui/desk/**                           window @desk-window
ui/lands.js                          window @desk-window
ui/styles/desk-*.css                 window @desk-window
ui/styles/inbox_desk.css             window @desk-window
tests/ui/specs/desk.mjs              window desk-*
ui/inbox/**                          window inbox* screens
ui/inbox_*.js                        window inbox* screens
ui/styles/inbox.css                  window inbox* screens
ui/mini.js                           window mini screens
ui/mini.html                         window mini screens
ui/styles/mini.css                   window mini screens
ui/file_view.js                      window file-view
ui/page_look.js                      window page-look text-size screens
ui/diff.js                           window diff-colours screens
ui/diff_overlay.js                   window diff-colours screens
ui/styles/diff.css                   window diff-colours screens
tests/ui/specs/fits.mjs              window fits
tests/ui/specs/shots.mjs             window screens
tests/ui/baseline/**                 window screens
tests/ui/specs/term.mjs              window terminal*

